from fastapi import FastAPI
from pydantic import BaseModel
import functools
from typing import ForwardRef

app = FastAPI()

class MyModel(BaseModel):
    name: str

def original_func(x: "MyModel"):
    return x

def wrapper(func):
    @functools.wraps(func)
    def wrapped(x: "MyModel"):
        return func(x)
    return wrapped

# Simulate different globals by manually setting __globals__ or using a different function
wrapped_func = wrapper(original_func)
wrapped_func.__globals__ = {} # This is a bit hacky, but simulates different globals

try:
    app.get("/")(wrapped_func)
    print("Success!")
except Exception as e:
    print(f"Error: {e}")
    import traceback
    traceback.print_exc()
